def compressedBasisMap {m : ℕ} (b : Module.Basis (Fin m) ℝ Y)
    (I : E →ₗ[ℝ] Y) (R : Y →ₗ[ℝ] E) (i : Fin m) : E →ₗ[ℝ] E :=
  R.comp ((basisCoordinateMap b i).comp I)

