def basisSignMultiplier {m : ℕ} (b : Module.Basis (Fin m) ℝ Y)
    (s : SignIndex m) (w : Fin m → ℝ) : Y →ₗ[ℝ] Y :=
  ∑ i, (realSignVector m s i * w i) • basisCoordinateMap b i

